(function(){
'use strict';
const Engine=window.MiyarManpower;if(!Engine)return;
const KEY='miyar-manpower-plans-v1';
const workspace=window.MiyarScenarioWorkspace.create({prefix:'mp',key:KEY,schema:'miyar-manpower-plan/1.0',calculate:Engine.plan,values:formValues,fill,renderResult:results,bindResult:bindResults,resultAttribute:'results',fromInput:i=>({...i,attritionPercent:i.attritionRate*100,productivityGainPercent:i.productivityGain*100,retirementsFte:i.retirementsFte??0,currentNationalFte:i.currentNationalFte??'',localizationTargetPercent:i.localizationTarget===null||i.localizationTarget===undefined?'':i.localizationTarget*100})});
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function ar(){return document.documentElement.lang!=='en';}function t(a,b){return ar()?a:b;}function fmt(n,d=1){return Number(n).toLocaleString(ar()?'ar-SA':'en-GB',{maximumFractionDigits:d});}
function readPlans(){return workspace.rows();}
function savePlan(p){return workspace.save(p);}
function input(id,label,value='',attrs='',hint=''){return '<label class="mp-field">'+label+'<input id="mp-'+id+'" value="'+esc(value)+'" '+attrs+(hint?' aria-describedby="mp-'+id+'-hint"':'')+'>'+(hint?'<small id="mp-'+id+'-hint" class="mp-hint">'+hint+'</small>':'')+'</label>';}
function signed(n,d=2){return (n>0?'+':n<0?'−':'')+fmt(Math.abs(n),d);}
function currentInstitution(){return window.MiyarInstitutionProfile?.read?.()||null;}
function formValues(){const scenarioOverrides={};for(const id of ['low','high'])scenarioOverrides[id]={demandFactor:Number(document.getElementById('mp-'+id+'-demand').value)/100,productivityDelta:Number(document.getElementById('mp-'+id+'-productivity').value)/100,attritionDelta:Number(document.getElementById('mp-'+id+'-attrition').value)/100};return {scenarioOverrides,strategyObjective:document.getElementById('mp-strategy').value,role:document.getElementById('mp-role').value,department:document.getElementById('mp-department').value,jobFamily:document.getElementById('mp-family').value,workloadUnit:document.getElementById('mp-unit').value,baselineWorkload:document.getElementById('mp-baseline').value,targetWorkload:document.getElementById('mp-target').value,capacityPerFte:document.getElementById('mp-capacity').value,currentFte:document.getElementById('mp-current').value,horizonYears:document.getElementById('mp-horizon').value,attritionPercent:document.getElementById('mp-attrition').value,committedHires:document.getElementById('mp-hires').value,internalSupply:document.getElementById('mp-internal').value,productivityGainPercent:document.getElementById('mp-productivity').value,annualCostPerFte:document.getElementById('mp-cost').value,retirementsFte:document.getElementById('mp-retirements')?.value??0,currentNationalFte:document.getElementById('mp-national')?.value??'',localizationTargetPercent:document.getElementById('mp-localization')?.value??''};}
function fill(e){for(const id of ['low','high']){const v=e.scenarioOverrides?.[id]||Engine.scenarioDefs[id];for(const [field,key] of [['demand','demandFactor'],['productivity','productivityDelta'],['attrition','attritionDelta']]){const el=document.getElementById('mp-'+id+'-'+field);if(el)el.value=Number(v[key])*100;}}for(const [k,v] of Object.entries({strategy:e.strategyObjective,role:e.role,department:e.department,family:e.jobFamily,unit:e.workloadUnit,baseline:e.baselineWorkload,target:e.targetWorkload,capacity:e.capacityPerFte,current:e.currentFte,horizon:e.horizonYears,attrition:e.attritionPercent,hires:e.committedHires,internal:e.internalSupply,productivity:e.productivityGainPercent,cost:e.annualCostPerFte,retirements:e.retirementsFte??0,national:e.currentNationalFte??'',localization:e.localizationTargetPercent??''})){const el=document.getElementById('mp-'+k);if(el)el.value=v??'';}}
function scenarioCard(s){const gap=s.final.rawGapFte,cls=gap>.5?'warn':gap<-.5?'surplus':'good';return '<article class="mp-scenario '+cls+'"><span>'+esc(ar()?s.labelAr:s.labelEn)+'</span><strong>'+fmt(s.final.rawRequiredFte,3)+' FTE</strong><small>'+t('المطلوب في نهاية الأفق','Required at horizon')+'</small><div><b>'+fmt(s.final.forecastSupplyFte)+'</b><span>'+t('العرض المتوقع','Forecast supply')+'</span></div><div><b class="mp-num">'+((gap>0?'+':'')+fmt(gap,3))+'</b><span>'+t('فجوة FTE','FTE gap')+'</span></div></article>';}
function baseTable(plan){const rows=plan.scenarios.base.years;return '<div class="mp-table-wrap"><table><thead><tr>'+[t('السنة','Year'),t('الطلب','Demand'),t('القدرة/FTE','Capacity/FTE'),t('FTE المطلوب','Required FTE'),t('العرض المتوقع','Forecast supply'),t('الفجوة','Gap'),t('عدد مقترح','Suggested headcount')].map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr><td>'+fmt(r.year,0)+'</td><td>'+fmt(r.demand)+'</td><td>'+fmt(r.capacityPerFte)+'</td><td>'+fmt(r.rawRequiredFte,3)+'</td><td>'+fmt(r.forecastSupplyFte)+'</td><td><span class="mp-num">'+((r.gapFte>0?'+':'')+fmt(r.rawGapFte,3))+'</span></td><td>'+fmt(r.recommendedHeadcount,0)+'</td></tr>').join('')+'</tbody></table></div>';}
function bridgeView(plan){const b=plan.bridge,tol=plan.input.actionToleranceFte,step=(label,value,cls='')=>'<li class="'+cls+'"><span>'+label+'</span><b>'+value+'</b></li>';let reading;
 if(b.gapFte>tol)reading=t('من فجوة '+fmt(b.gapFte,2)+' FTE: ','Of the '+fmt(b.gapFte,2)+' FTE gap: ')+(b.replacementFte>0?t(fmt(b.replacementFte,2)+' FTE لتعويض المغادرين المتوقعين — إحلال لمناصب ممولة أصلًا؛ ',fmt(b.replacementFte,2)+' FTE replaces expected leavers — backfill of already-budgeted positions; '):'')+(b.growthFte>0?t(fmt(b.growthFte,2)+' FTE من نمو الطلب — مناصب جديدة تحتاج اعتماد ميزانية.',fmt(b.growthFte,2)+' FTE comes from demand growth — new positions that need budget approval.'):t('الطلب لا يتجاوز القدرة الحالية؛ الفجوة ناتجة عن المغادرة، فراجع ضرورة كل إحلال قبل التعويض المماثل.','Demand does not exceed current capacity; the gap comes from leavers, so review whether each exit needs a like-for-like replacement.'))+(b.pipelineFte>0?t(' التعيينات والنقل المعتمد تغطي '+fmt(b.pipelineFte,2)+' FTE.',' Committed hires and internal moves already cover '+fmt(b.pipelineFte,2)+' FTE.'):'');
 else if(b.gapFte<-tol)reading=t('فائض محتمل '+fmt(Math.abs(b.gapFte),2)+' FTE عند نهاية الأفق: راجع إعادة التوزيع والاستنزاف الطبيعي قبل أي توظيف. هذا تقدير تخطيطي وليس قرار استغناء.','Potential surplus of '+fmt(Math.abs(b.gapFte),2)+' FTE at the horizon: review redeployment and natural attrition before any hiring. This is a planning estimate, not a redundancy decision.');
 else reading=t('العرض والطلب متوازنان ضمن هامش ±0.5 FTE؛ لا يُقترح عدد إضافي. راقب مؤشرات الطلب والإنتاجية.','Supply and demand balance within ±0.5 FTE; no additional headcount is proposed. Monitor demand and productivity indicators.');
 return '<div class="mp-bridge"><h3>'+t('جسر القوى العاملة — من الوضع الحالي إلى نهاية الأفق (الأساس)','Workforce bridge — from today to the horizon (base)')+'</h3><ol>'+step(t('FTE الحالي','Current FTE'),fmt(b.currentFte,2))+step(t('مغادرون متوقعون (استنزاف)','Expected leavers (attrition)'),signed(-b.attritionExitsFte),'out')+step(t('تقاعد/انتهاء عقود معروف','Known retirements / contract ends'),signed(-b.knownExitsFte),'out')+step(t('تعيينات ونقل معتمد','Committed hires & internal moves'),signed(b.pipelineFte),'in')+step(t('العرض المتوقع','Forecast supply'),fmt(b.forecastSupplyFte,2),'total')+step(t('FTE المطلوب','Required FTE'),fmt(b.requiredFte,2),'total')+step(t('الفجوة','Gap'),signed(b.gapFte),'gap')+'</ol><p>'+esc(reading)+'</p></div>';}
function optionsView(plan){if(!plan.options.length){const a=plan.actions[0];return '<div class="mp-hold"><strong>'+t(a.type==='move'?'إعادة توزيع قبل التوظيف':'متابعة دون توظيف إضافي',a.type==='move'?'Redeploy before hiring':'Monitor without additional hiring')+'</strong><p>'+esc(ar()?a.textAr:a.textEn)+'</p></div>';}
 const card=(o)=>{const s=o.sensitivity;let title,body;
  if(o.id==='buy'){title=t('شراء · توظيف خارجي','Buy · external hiring');body=t('حتى '+fmt(o.headcount,0)+' منصب عند ندرة المهارة داخليًا أو إلحاح التوقيت. أدرج مدة الشغل المعتادة لدى الجهة في خطة التوظيف.','Up to '+fmt(o.headcount,0)+' position(s) when the skill is scarce internally or timing is urgent. Build the organization’s usual time-to-fill into the hiring plan.');}
  else if(o.id==='build'){title=t('بناء · تطوير داخلي','Build · develop internally');body=t('طوّر أو أعد تأهيل موظفين بمهارات قريبة قبل فتح شواغر؛ مناسب عندما يتسع الأفق لمدة التطوير.','Upskill or reskill employees with adjacent skills before opening vacancies; fits when the horizon allows development time.');}
  else if(o.id==='borrow'){title=t('استعارة · موارد مرنة','Borrow · flexible resources');body=o.flexFte>0?t('فرق الفجوة بين الطلب الأقل والمرتفع ≈ '+fmt(o.flexFte,2)+' FTE. وظّف دائمًا للحد المؤكد ('+fmt(o.coreFte,2)+' FTE) وغطِّ الباقي بتعاقد أو إعارة أو إسناد.','The gap spread between lower and higher demand is ≈ '+fmt(o.flexFte,2)+' FTE. Hire permanently for the firm floor ('+fmt(o.coreFte,2)+' FTE) and cover the rest through contracts, secondment or outsourcing.'):t('تعاقد أو إعارة أو إسناد للاحتياج المؤقت أو غير المؤكد.','Contracts, secondment or outsourcing for temporary or uncertain demand.');}
  else if(o.id==='bind'){title=t('احتفاظ · خفض الاستنزاف','Bind · retain talent');body=s?t('خفض الاستنزاف '+fmt(Math.abs(s.step),1)+' نقطة مئوية يغيّر الفجوة بمقدار '+signed(s.gapDeltaFte)+' FTE.','Reducing attrition by '+fmt(Math.abs(s.step),1)+' pp changes the gap by '+signed(s.gapDeltaFte)+' FTE.'):t('الاستنزاف المدخل صفر؛ لا أثر للاحتفاظ على هذه الفجوة.','Entered attrition is zero; retention does not change this gap.');}
  else {title=t('أتمتة · تحسين العمليات','Bot · automate & improve');body=t('كل +5 نقاط مئوية في الإنتاجية تغيّر الفجوة بمقدار '+signed(s.gapDeltaFte)+' FTE — بشرط مبادرة ممولة ومقاسة.','Each +5 pp of productivity changes the gap by '+signed(s.gapDeltaFte)+' FTE — only with a funded, measured initiative.');}
  return '<article data-mp-option="'+o.id+'"><strong>'+title+'</strong><p>'+esc(body)+'</p></article>';};
 return '<div class="mp-options"><h3>'+t('خيارات سد الفجوة — Buy · Build · Borrow · Bind · Bot','Options to close the gap — Buy · Build · Borrow · Bind · Bot')+'</h3><p>'+t('بدائل للفجوة نفسها وليست أعدادًا تُجمع؛ اختر مزيجًا وراجعه مع الأعمال والمالية.','Alternatives for the same gap, not quantities to add up; choose a mix and review it with the business and Finance.')+'</p><div class="mp-option-grid">'+plan.options.map(card).join('')+'</div></div>';}
function sensitivityView(plan){const gap=plan.scenarios.base.final.rawGapFte,names={demand:[t('الطلب المستهدف','Target demand'),t('+10%','+10%')],productivity:[t('الإنتاجية','Productivity'),t('+5 نقاط مئوية','+5 pp')],attrition:[t('الاستنزاف','Attrition'),null],pipeline:[t('تعيين معتمد إضافي','One more committed hire'),'+1 FTE']};
 return '<div class="mp-sensitivity"><h3>'+t('ما الذي يحرّك الفجوة؟ — السيناريو الأساسي','What moves the gap? — base scenario')+'</h3><div class="mp-sens-wrap"><table><thead><tr><th>'+t('العامل','Lever')+'</th><th>'+t('التغيير','Change')+'</th><th>'+t('أثره على الفجوة (FTE)','Gap change (FTE)')+'</th><th>'+t('الفجوة بعد التغيير','Resulting gap')+'</th></tr></thead><tbody>'+plan.sensitivity.map(r=>{const n=names[r.driver],change=n[1]||t('−'+fmt(Math.abs(r.step),1)+' نقطة مئوية','−'+fmt(Math.abs(r.step),1)+' pp');return '<tr><td>'+n[0]+'</td><td>'+change+'</td><td><span class="mp-num">'+signed(r.gapDeltaFte)+'</span></td><td><span class="mp-num">'+signed(gap+r.gapDeltaFte)+'</span></td></tr>';}).join('')+'</tbody></table></div></div>';}
function localizationView(plan){const l=plan.localization;if(!l)return '';const status=l.minimumNationalHires>0?t('لتحقيق الهدف يلزم أن يكون '+fmt(l.minimumNationalHires,0)+' على الأقل من التعيينات أو النقل الداخلي مواطنين.','At least '+fmt(l.minimumNationalHires,0)+' of the hires or internal moves must be nationals to reach the target.')+(l.exceedsTotalGap?t(' الهدف يتجاوز فجوة العدد؛ يلزم أيضًا شغل مناصب قائمة بمواطنين عند شغورها.',' The target exceeds the headcount gap; nationals must also fill existing positions as they become vacant.'):''):t('العرض المتوقع من المواطنين يحقق الهدف وفق الافتراضات الحالية.','Projected national supply meets the target under the current assumptions.');
 return '<div class="mp-localization"><h3>'+t('التوطين — هدف الجهة عند نهاية الأفق','Localization — organization target at the horizon')+'</h3><div class="mp-assumptions"><div><b>'+(l.currentRatePercent===null?'—':fmt(l.currentRatePercent)+'%')+'</b><span>'+t('نسبة التوطين الحالية','Current localization rate')+'</span></div><div><b>'+fmt(l.targetPercent)+'%</b><span>'+t('الهدف المدخل','Entered target')+'</span></div><div><b>'+fmt(l.requiredNationalFte,2)+'</b><span>'+t('FTE مواطنين مطلوب','National FTE required')+'</span></div><div><b>'+fmt(l.projectedNationalSupplyFte,2)+'</b><span>'+t('عرض المواطنين المتوقع','Projected national supply')+'</span></div></div><p><strong>'+status+'</strong></p><small>'+t('هدف تدخله الجهة؛ ليس احتسابًا لنطاقات ولا قرارًا نظاميًا. تحقّق من المتطلب الساري قبل الاعتماد.','Organization-entered target; not a Nitaqat calculation or regulatory determination. Verify the currently applicable requirement before approval.')+'</small></div>';}
function decisionSummary(plan){const b=plan.bridge,base=plan.scenarios.base.final,tol=plan.input.actionToleranceFte,flex=plan.flexibility;let text;
 if(b.gapFte>tol)text=t('خطّط لـ '+fmt(base.gapHeadcount,0)+' منصب: نحو '+fmt(Math.max(0,b.replacementFte),2)+' FTE إحلال للمغادرين ضمن الميزانية القائمة، و'+fmt(Math.max(0,b.growthFte),2)+' FTE نمو يحتاج اعتماد ميزانية.','Plan for '+fmt(base.gapHeadcount,0)+' position(s): about '+fmt(Math.max(0,b.replacementFte),2)+' FTE backfills expected leavers within the existing budget and '+fmt(Math.max(0,b.growthFte),2)+' FTE is growth that needs budget approval.')+(flex&&flex.flexFte>0?t(' غطِّ تذبذب الطلب (≈ '+fmt(flex.flexFte,2)+' FTE) بموارد مرنة.',' Cover the demand swing (≈ '+fmt(flex.flexFte,2)+' FTE) with flexible resources.'):'');
 else if(b.gapFte<-tol)text=t('لا توظيف جديد: فائض محتمل '+fmt(Math.abs(b.gapFte),2)+' FTE؛ راجع إعادة التوزيع والاستنزاف الطبيعي.','No new hiring: a potential surplus of '+fmt(Math.abs(b.gapFte),2)+' FTE; review redeployment and natural attrition.');
 else text=t('لا حاجة لعدد إضافي؛ العرض والطلب متوازنان ضمن ±0.5 FTE.','No additional headcount needed; supply and demand balance within ±0.5 FTE.');
 return '<div class="decision-summary"><strong>'+t('ماذا يعني هذا لقرارك؟','What this means for your decision')+'</strong><p>'+esc(text)+'</p></div>';}
function results(plan){const base=plan.scenarios.base,high=plan.scenarios.high,low=plan.scenarios.low,cost=base.final.annualGapCost;return '<section class="mp-results"><div class="mp-result-head"><div><span>'+t('تقدير سيناريو','SCENARIO ESTIMATE')+'</span><h2>'+esc(plan.input.role||plan.input.jobFamily||t('خطة القوى العاملة','Workforce plan'))+'</h2><p>'+esc(plan.input.strategyObjective||t('خطة مبنية على مدخلات الطلب والقدرة.','Plan based on demand and capacity inputs.'))+'</p></div><span class="mp-horizon">'+fmt(plan.input.horizonYears,0)+' '+t('سنوات','years')+'</span></div>'+decisionSummary(plan)+'<div class="mp-scenarios">'+scenarioCard(low)+scenarioCard(base)+scenarioCard(high)+'</div><div class="mp-assumptions"><div><b>'+fmt(base.assumptions.annualDemandGrowthPercent)+'%</b><span>'+t('نمو الطلب السنوي · Base','Annual demand growth · Base')+'</span></div><div><b>'+fmt(base.assumptions.cumulativeProductivityPercent)+'%</b><span>'+t('تحسن الإنتاجية التراكمي','Cumulative productivity gain')+'</span></div><div><b>'+fmt(base.assumptions.annualAttritionPercent)+'%</b><span>'+t('الاستنزاف السنوي','Annual attrition')+'</span></div><div><b>'+(cost===null?'—':fmt(cost,0)+' SAR')+'</b><span>'+t('تكلفة الفجوة السنوية عند الأفق','Annual gap cost at horizon')+'</span></div></div><h3>'+t('المسار السنوي — السيناريو الأساسي','Annual path — base scenario')+'</h3>'+baseTable(plan)+bridgeView(plan)+optionsView(plan)+sensitivityView(plan)+localizationView(plan)+'<div class="mp-uncertainty"><strong>'+t('المجهول يبقى ظاهرًا','Uncertainty stays visible')+'</strong><p>'+esc(t('النتيجة تقدير سيناريو، وليست اعتماد عدد. يجب مراجعة الطلب، القدرة، الاستنزاف، توقيت التوظيف، الإنتاجية والميزانية مع الأعمال والمالية قبل القرار.','This is a scenario estimate, not an approved headcount. Demand, capacity, attrition, hiring timing, productivity and budget must be reviewed with the business and Finance before a decision.'))+'</p></div><div class="action-row"><button class="button button-primary" type="button" data-mp-save>'+t('حفظ الخطة','Save plan')+'</button>'+(base.final.rawGapFte>.5?'<button class="button button-outline" type="button" data-mp-od>'+t('تحويل الفجوة إلى طلب OD','Send gap to OD')+'</button>':'')+'<button class="button button-outline" type="button" data-mp-export>'+t('تصدير JSON','Export JSON')+'</button></div><p data-mp-status role="status"></p></section>';}
function download(plan){const url=URL.createObjectURL(new Blob([JSON.stringify(plan,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='miyar-manpower-plan.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
function handoff(plan){const b=plan.scenarios.base.final,gap=b.gapHeadcount;if(b.rawGapFte<=.5)return;sessionStorage.setItem('miyar-manpower-handoff',JSON.stringify({strategyObjective:plan.input.strategyObjective,role:plan.input.role,department:plan.input.department,jobFamily:plan.input.jobFamily,headcount:gap,constraints:'Manpower planning evidence: horizon '+plan.input.horizonYears+' years; base required '+b.rawRequiredFte+' FTE; forecast supply '+b.forecastSupplyFte+' FTE; gap '+b.rawGapFte+' FTE. Validate responsibilities and job design before approval.'}));location.hash='#enterprise/create';window.dispatchEvent(new Event('hashchange'));}
function bindResults(plan){const root=document.querySelector('.mp-results');root.querySelector('[data-mp-save]').onclick=()=>{try{const r=savePlan(plan);root.querySelector('[data-mp-status]').textContent=t('حُفظت الخطة محليًا: ','Plan saved locally: ')+r.id;}catch(e){workspace.fail(e);}};root.querySelector('[data-mp-export]').onclick=()=>download(plan);const od=root.querySelector('[data-mp-od]');if(od)od.onclick=()=>handoff(plan);}
function render(){if(location.hash!=='#enterprise/manpower')return;const content=document.getElementById('ent-content');if(!content)return;const p=currentInstitution(),profileNote=p?.version?t('يستخدم الإصدار المؤسسي v','Using institution profile v')+p.version:t('لم يُعتمد إعداد مؤسسي بعد؛ ستبقى الإدارة والعائلة نصوصًا يراجعها المستخدم.','No institution profile configured yet; department and family remain user-reviewed text.');document.getElementById('enterprise-heading').textContent=t('تخطيط القوى العاملة','Manpower planning');const bc=document.getElementById('breadcrumb-title');if(bc)bc.textContent=t('تخطيط القوى العاملة','Manpower planning');document.querySelectorAll('.nav-link').forEach(x=>x.classList.remove('active'));document.querySelector('[data-manpower-nav]')?.classList.add('active');content.innerHTML='<section class="mp-page"><div class="mp-heading"><div><span>'+t('المرحلة 2 · تخطيط القوى العاملة','PHASE 2 · MANPOWER PLANNING')+'</span><h2>'+t('من الطلب الاستراتيجي إلى فجوة قوى عاملة قابلة للفحص','From strategic demand to an inspectable workforce gap')+'</h2><p>'+t('لا يتنبأ معيار بعدد سحري. أنت تدخل الطلب والقدرة والعرض والافتراضات؛ المحرك يعرض الحساب والسيناريوهات والمجهول.','Miyar does not invent a magic headcount. You provide demand, capacity, supply and assumptions; the engine exposes the calculation, scenarios and uncertainty.')+'</p></div><button type="button" class="button button-outline" data-mp-example>'+t('تحميل مثال HC','Load HC example')+'</button></div><div class="mp-profile-note">'+esc(profileNote)+'</div><div class="mp-form"><div class="mp-wide"><label class="mp-field">'+t('الهدف الاستراتيجي','Strategic objective')+'<textarea id="mp-strategy" rows="3"></textarea></label></div>'+input('role',t('الدور / المنصب المرجعي','Role / reference position'))+input('department',t('الإدارة','Department'))+input('family',t('العائلة الوظيفية','Job family'))+input('unit',t('وحدة قياس عبء العمل','Workload unit'),'workload units','',t('محرك العمل: معاملات، حالات، مشاريع موزونة…','The workload driver: transactions, cases, weighted projects…'))+input('baseline',t('عبء العمل الحالي','Current workload'),'100','type="number" min="0.01" step="any"')+input('target',t('عبء العمل المستهدف عند نهاية الأفق','Target workload at horizon'),'130','type="number" min="0.01" step="any"')+input('capacity',t('قدرة FTE واحدة حاليًا','Current capacity per FTE'),'50','type="number" min="0.01" step="any"',t('صافي الإنجاز السنوي بعد الإجازات والتدريب والغياب.','Net annual output after leave, training and absence.'))+input('current',t('FTE الحالي','Current FTE'),'2','type="number" min="0" step="0.1"')+input('horizon',t('الأفق بالسنوات','Horizon years'),'3','type="number" min="1" max="10" step="1"')+input('attrition',t('الاستنزاف السنوي %','Annual attrition %'),'5','type="number" min="0" max="50" step="0.1"',t('المغادرة الطوعية وغير الطوعية دون التقاعد المعروف.','Voluntary and involuntary leavers, excluding known retirements.'))+input('retirements',t('تقاعد/انتهاء عقود معروف خلال الأفق (FTE)','Known retirements / contract ends over the horizon (FTE)'),'0','type="number" min="0" step="0.1"')+input('hires',t('توظيفات معتمدة خلال الأفق','Committed hires over horizon'),'0','type="number" min="0" step="0.1"')+input('internal',t('نقل/تطوير داخلي سيضيف FTE','Internal moves/upskilling adding FTE'),'0','type="number" min="0" step="0.1"')+input('productivity',t('تحسن إنتاجية تراكمي %','Cumulative productivity gain %'),'10','type="number" min="-50" max="200" step="0.1"')+input('cost',t('التكلفة السنوية لكل FTE — اختياري','Annual cost per FTE — optional'),'','type="number" min="0" step="1"')+'</div><details class="mp-scenario-controls"><summary>'+t('افتراضات السيناريوهات — تعديل مستقل','Scenario assumptions — independent controls')+'</summary><p>'+t('افتراضيًا يتغير الطلب فقط. الإنتاجية والاستنزاف نقاط مئوية مضافة للأساس. هامش المتابعة ±0.5 FTE؛ داخله لا يُقترح عدد إضافي.','Only demand varies by default. Productivity and attrition are percentage-point changes to the base. Monitoring tolerance is ±0.5 FTE; no additional headcount is proposed inside it.')+'</p><div class="mp-form">'+['low','high'].map(id=>input(id+'-demand',t(id==='low'?'الطلب الأقل % من الأساس':'الطلب الأعلى % من الأساس',id==='low'?'Low demand % of base':'High demand % of base'),id==='low'?90:110,'type="number" min="1" max="500" step="any"')+input(id+'-productivity',t('تغير الإنتاجية — ','Productivity change — ')+id,0,'type="number" min="-50" max="200" step="any"')+input(id+'-attrition',t('تغير الاستنزاف — ','Attrition change — ')+id,0,'type="number" min="-50" max="50" step="any"')).join('')+'</div></details><details class="mp-scenario-controls mp-localization-controls"><summary>'+t('التوطين — اختياري','Localization — optional')+'</summary><p>'+t('أدخل عدد المواطنين الحالي وهدف الجهة لمعرفة الحد الأدنى من تعيينات المواطنين. لا يحسب معيار نطاقات ولا يفترض نسبة نظامية.','Enter current national FTE and the organization target to see the minimum national hiring. Miyar does not calculate Nitaqat bands or assume a regulatory percentage.')+'</p><div class="mp-form">'+input('national',t('FTE المواطنين الحاليين','Current national FTE'),'','type="number" min="0" step="0.1"')+input('localization',t('هدف التوطين للجهة %','Organization localization target %'),'','type="number" min="0" max="100" step="0.1"')+'</div></details><div class="mp-run"><button type="button" class="button button-primary" data-mp-run>'+t('احسب الفجوة والسيناريوهات','Calculate gap & scenarios')+'</button><span data-mp-message role="status">'+t('كل الأرقام افتراضات قابلة للتعديل حتى يتم اعتماد بيانات المؤسسة.','All figures remain editable assumptions until organization data is approved.')+'</span></div><div data-mp-results></div></section>';content.querySelector('[data-mp-example]').onclick=()=>workspace.example(Engine.example);content.querySelector('[data-mp-run]').onclick=()=>workspace.calculate();workspace.mount(content);}

function ensureNav(){const nav=document.querySelector('.sidebar nav.nav-list');if(!nav)return;let link=nav.querySelector('[data-manpower-nav]');if(!link){link=document.createElement('a');link.href='#enterprise/manpower';link.className='nav-link';link.dataset.manpowerNav='true';link.innerHTML='<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20h16M7 16v-5m5 5V5m5 11V8"/></svg><span>'+t('تخطيط القوى العاملة','Manpower planning')+'</span>';const create=nav.querySelector('[data-enterprise-open="create"]');create?.after(link);}else link.querySelector('span').textContent=t('تخطيط القوى العاملة','Manpower planning');}
function consumeHandoff(){if(location.hash!=='#enterprise/create')return;let value;try{value=JSON.parse(sessionStorage.getItem('miyar-manpower-handoff')||'null');}catch{}if(!value)return;const panel=document.getElementById('miyar-od-workbench');if(!panel)return;sessionStorage.removeItem('miyar-manpower-handoff');const set=(sel,v)=>{const e=panel.querySelector(sel);if(e){e.value=v||'';e.dispatchEvent(new Event('input',{bubbles:true}));}};set('[data-od-strategy]',value.strategyObjective);set('[data-od-department]',value.department);set('[data-od-constraints]',value.constraints);const h=document.querySelector('[data-number="headcount"]');if(h){h.value=value.headcount;h.dispatchEvent(new Event('input',{bubbles:true}));}const status=panel.querySelector('[data-od-status]');if(status)status.textContent=t('تم استيراد فجوة القوى العاملة. أضف المسؤوليات الفعلية ثم ولّد/راجع حزمة OD.','Workforce gap imported. Add actual responsibilities, then generate/review the OD package.');panel.scrollIntoView({block:'start'});}
window.addEventListener('hashchange',()=>setTimeout(()=>{ensureNav();render();consumeHandoff();},0));window.addEventListener('miyar:navigate',()=>setTimeout(()=>{ensureNav();render();consumeHandoff();},0));document.addEventListener('click',e=>{const link=e.target.closest('[data-manpower-nav]');if(link){e.preventDefault();location.hash='#enterprise/manpower';setTimeout(render,0);}});setTimeout(()=>{ensureNav();render();consumeHandoff();},0);
window.MiyarManpowerWorkbench={render,readPlans,KEY,getResult:workspace.result};
})();
